[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<meta name="description" content="Global Aid Alliance — A humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide.">
<title>Global Aid Alliance — Together We Respond</title>
<style>
/* ── Reset & Base ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  /* Brand colors */
  --brand-red: #C41E3A;
  --brand-red-dark: #9B182E;
  --brand-red-light: #FDE8EC;
  --brand-navy: #1B3A5C;
  --brand-navy-dark: #11273D;
  --brand-white: #FFFFFF;

  /* OKLCH-derived supporting palette */
  --text-primary: oklch(18% 0.02 260);
  --text-secondary: oklch(42% 0.02 260);
  --text-muted: oklch(55% 0.01 260);
  --bg-warm: oklch(97% 0.005 80);
  --bg-cool: oklch(97% 0.005 255);
  --border-light: oklch(88% 0.008 260);
  --border-medium: oklch(78% 0.01 260);
  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 16px oklch(0% 0 0 / 0.1);
  --shadow-lg: 0 8px 32px oklch(0% 0 0 / 0.14);
  --shadow-xl: 0 16px 48px oklch(0% 0 0 / 0.18);

  /* Spacing scale (8px base) */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;

  /* Typography */
  --font-heading: 'Segoe UI', system-ui, -apple-system, sans-serif;
  --font-body: 'Segoe UI', system-ui, -apple-system, sans-serif;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;

  /* Transitions */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-in-out: cubic-bezier(0.65, 0, 0.35, 1);
  --duration-fast: 150ms;
  --duration-base: 250ms;
  --duration-slow: 400ms;

  /* Layout */
  --max-width: 1200px;
}

html {
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  font-family: var(--font-body);
  font-size: 1rem;
  line-height: 1.6;
  color: var(--text-primary);
  background: var(--brand-white);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

img { max-width: 100%; height: auto; display: block; }

a { color: var(--brand-navy); text-decoration: none; }
a:hover { text-decoration: underline; }

:focus-visible {
  outline: 2px solid var(--brand-navy);
  outline-offset: 2px;
}

/* ── Utility ── */
.sr-only {
  position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--space-4);
}

/* ── Buttons ── */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2);
  padding: 14px 28px;
  font-size: 1rem; font-weight: 600; font-family: var(--font-body);
  border: 2px solid transparent; border-radius: var(--radius-sm);
  cursor: pointer; transition: all var(--duration-fast) var(--ease-out);
  white-space: nowrap; min-height: 48px; min-width: 48px;
}
.btn-primary {
  background: var(--brand-red); color: var(--brand-white);
}
.btn-primary:hover { background: var(--brand-red-dark); }
.btn-primary:active { transform: scale(0.98); }

.btn-secondary {
  background: transparent; color: var(--brand-white); border-color: var(--brand-white);
}
.btn-secondary:hover { background: oklch(100% 0 0 / 0.12); }
.btn-secondary:active { transform: scale(0.98); }

.btn-outline {
  background: transparent; color: var(--brand-red); border-color: var(--brand-red);
}
.btn-outline:hover { background: var(--brand-red-light); }
.btn-outline:active { transform: scale(0.98); }

.btn-navy {
  background: var(--brand-navy); color: var(--brand-white);
}
.btn-navy:hover { background: var(--brand-navy-dark); }
.btn-navy:active { transform: scale(0.98); }

/* ── Header ── */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: var(--brand-white);
  border-bottom: 1px solid var(--border-light);
  transition: box-shadow var(--duration-base) var(--ease-out);
}
.site-header.scrolled { box-shadow: var(--shadow-md); }

.header-inner {
  display: flex; align-items: center; justify-content: space-between;
  max-width: var(--max-width); margin: 0 auto;
  padding: 0 var(--space-4); height: 68px;
}

.header-logo {
  display: flex; align-items: center; gap: var(--space-2);
  font-weight: 700; font-size: 1.1rem; color: var(--brand-navy);
  text-decoration: none; white-space: nowrap;
}
.header-logo:hover { text-decoration: none; }
.header-logo-icon {
  width: 36px; height: 36px; background: var(--brand-red); border-radius: var(--radius-sm);
  display: flex; align-items: center; justify-content: center;
  color: var(--brand-white); font-size: 1.3rem; flex-shrink: 0;
}

.header-nav { display: flex; align-items: center; gap: var(--space-2); }

.header-nav a {
  padding: var(--space-1) var(--space-2); font-size: 0.925rem;
  font-weight: 500; color: var(--text-primary); border-radius: var(--radius-sm);
  transition: background var(--duration-fast);
}
.header-nav a:hover { background: var(--bg-warm); text-decoration: none; }

.header-utility {
  display: flex; align-items: center; gap: var(--space-3);
  margin-left: var(--space-3);
  padding-left: var(--space-3);
  border-left: 1px solid var(--border-light);
}
.header-utility a {
  font-size: 0.825rem; color: var(--text-muted);
}
.header-utility a:hover { color: var(--text-primary); }

.header-donate-btn { margin-left: var(--space-3); }

/* Hamburger */
.hamburger {
  display: none; background: none; border: none; cursor: pointer;
  width: 48px; height: 48px; padding: 12px;
  flex-direction: column; justify-content: center; gap: 6px;
  border-radius: var(--radius-sm);
}
.hamburger:hover { background: var(--bg-warm); }
.hamburger span {
  display: block; width: 24px; height: 2.5px; background: var(--text-primary);
  border-radius: 2px; transition: all var(--duration-base) var(--ease-out);
  transform-origin: center;
}
.hamburger.active span:nth-child(1) { transform: translateY(8.5px) rotate(45deg); }
.hamburger.active span:nth-child(2) { opacity: 0; transform: scaleX(0); }
.hamburger.active span:nth-child(3) { transform: translateY(-8.5px) rotate(-45deg); }

/* Mobile nav drawer */
.mobile-nav {
  display: none; position: fixed; top: 68px; left: 0; right: 0; bottom: 0;
  background: var(--brand-white); z-index: 99; padding: var(--space-4);
  flex-direction: column; gap: var(--space-1); overflow-y: auto;
  transform: translateX(100%); transition: transform var(--duration-slow) var(--ease-out);
}
.mobile-nav.open { transform: translateX(0); }
.mobile-nav a {
  display: block; padding: 14px var(--space-3); font-size: 1.05rem;
  font-weight: 500; color: var(--text-primary); border-radius: var(--radius-sm);
}
.mobile-nav a:hover { background: var(--bg-warm); text-decoration: none; }
.mobile-nav .btn-primary { margin-top: var(--space-3); text-align: center; }
.mobile-utility {
  display: flex; gap: var(--space-3); padding: var(--space-3); margin-top: var(--space-3);
  border-top: 1px solid var(--border-light);
}
.mobile-utility a { font-size: 0.9rem; color: var(--text-muted); padding: 0; }

/* Overlay when mobile nav open */
.mobile-nav-overlay {
  display: none; position: fixed; inset: 0; top: 68px; background: oklch(0% 0 0 / 0.5);
  z-index: 98; opacity: 0; transition: opacity var(--duration-base);
}
.mobile-nav-overlay.active { display: block; opacity: 1; }

/* ── Hero ── */
.hero {
  position: relative; min-height: 580px;
  background: linear-gradient(135deg, var(--brand-navy-dark) 0%, var(--brand-navy) 60%, oklch(28% 0.09 260) 100%);
  display: flex; align-items: center; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; inset: 0;
  background:
    radial-gradient(ellipse 80% 60% at 20% 80%, oklch(52% 0.18 20 / 0.2) 0%, transparent 60%),
    radial-gradient(ellipse 60% 50% at 80% 20%, oklch(45% 0.12 260 / 0.25) 0%, transparent 60%);
}
.hero::after {
  content: ''; position: absolute; inset: 0;
  background-image:
    repeating-linear-gradient(45deg, transparent, transparent 3px, oklch(100% 0 0 / 0.015) 3px, oklch(100% 0 0 / 0.015) 6px);
  opacity: 0.6;
}

.hero-content {
  position: relative; z-index: 1;
  max-width: var(--max-width); margin: 0 auto; padding: var(--space-8) var(--space-4);
  color: var(--brand-white);
}

.hero-badge {
  display: inline-block; padding: 6px 16px; margin-bottom: var(--space-4);
  background: oklch(100% 0 0 / 0.12); border: 1px solid oklch(100% 0 0 / 0.2);
  border-radius: 100px; font-size: 0.85rem; font-weight: 600;
  letter-spacing: 0.04em; text-transform: uppercase;
}

.hero h1 {
  font-size: clamp(2.4rem, 5vw, 3.8rem); font-weight: 800; line-height: 1.12;
  max-width: 680px; margin-bottom: var(--space-4); letter-spacing: -0.02em;
}

.hero-subtitle {
  font-size: clamp(1.05rem, 1.8vw, 1.2rem); line-height: 1.6;
  max-width: 580px; margin-bottom: var(--space-5); opacity: 0.9;
}

.hero-ctas { display: flex; flex-wrap: wrap; gap: var(--space-3); }

/* ── Section Base ── */
.section { padding: var(--space-8) var(--space-4); }
.section-alt { background: var(--bg-warm); }
.section-dark { background: var(--brand-navy); color: var(--brand-white); }

.section-label {
  display: inline-block; font-size: 0.8rem; font-weight: 700; letter-spacing: 0.08em;
  text-transform: uppercase; color: var(--brand-red); margin-bottom: var(--space-2);
}

.section-title {
  font-size: clamp(1.8rem, 3vw, 2.5rem); font-weight: 700; line-height: 1.2;
  color: var(--text-primary); margin-bottom: var(--space-3); letter-spacing: -0.01em;
}
.section-dark .section-title { color: var(--brand-white); }

.section-body {
  font-size: 1.1rem; line-height: 1.7; color: var(--text-secondary); max-width: 720px;
}
.section-dark .section-body { color: oklch(100% 0 0 / 0.8); }

/* ── Mission ── */
.mission-content {
  display: grid; grid-template-columns: 1fr; gap: var(--space-6);
  align-items: start;
}

.mission-principles {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-4); margin-top: var(--space-5);
}
.mission-principle {
  padding: var(--space-4); background: var(--bg-cool); border-radius: var(--radius-md);
  border-left: 3px solid var(--brand-red);
}
.mission-principle h3 { font-size: 1rem; font-weight: 700; margin-bottom: var(--space-1); color: var(--brand-navy); }
.mission-principle p { font-size: 0.925rem; color: var(--text-secondary); line-height: 1.55; }

/* ── Impact Stats ── */
.impact-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-4);
}
.impact-card {
  text-align: center; padding: var(--space-6) var(--space-4);
  background: oklch(100% 0 0 / 0.06); border-radius: var(--radius-lg);
  border: 1px solid oklch(100% 0 0 / 0.1);
  transition: transform var(--duration-base) var(--ease-out);
}
.impact-card:hover { transform: translateY(-4px); }

.impact-number {
  font-size: clamp(2.2rem, 4vw, 3.2rem); font-weight: 800; line-height: 1.1;
  color: var(--brand-white); margin-bottom: var(--space-1); letter-spacing: -0.02em;
}
.impact-number sup { font-size: 0.55em; vertical-align: super; font-weight: 600; }
.impact-label {
  font-size: 1.02rem; color: oklch(100% 0 0 / 0.75); font-weight: 500;
}

/* ── Programs Accordion ── */
.programs-grid {
  display: grid; gap: var(--space-2); margin-top: var(--space-5);
}
.accordion-item {
  border: 1px solid var(--border-light); border-radius: var(--radius-md);
  overflow: hidden; background: var(--brand-white);
  transition: box-shadow var(--duration-base);
}
.accordion-item:hover { box-shadow: var(--shadow-sm); }
.accordion-item.active { border-color: var(--brand-red); box-shadow: var(--shadow-sm); }

.accordion-trigger {
  width: 100%; padding: var(--space-4); display: flex; align-items: center;
  justify-content: space-between; gap: var(--space-3);
  background: none; border: none; cursor: pointer;
  font-family: var(--font-body); font-size: 1.1rem; font-weight: 600;
  color: var(--text-primary); text-align: left;
  min-height: 48px;
}
.accordion-trigger:hover { background: var(--bg-warm); }

.accordion-icon {
  width: 32px; height: 32px; flex-shrink: 0; border-radius: 50%;
  background: var(--bg-warm); display: flex; align-items: center; justify-content: center;
  transition: transform var(--duration-base) var(--ease-out), background var(--duration-fast);
  font-size: 1.2rem; color: var(--text-muted);
}
.accordion-item.active .accordion-icon {
  transform: rotate(45deg); background: var(--brand-red-light); color: var(--brand-red);
}

.accordion-panel {
  max-height: 0; overflow: hidden;
  transition: max-height var(--duration-slow) var(--ease-out);
}
.accordion-panel-inner {
  padding: 0 var(--space-4) var(--space-4);
  color: var(--text-secondary); font-size: 1rem; line-height: 1.65;
}

/* ── Get Involved ── */
.involved-grid {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--space-4);
  margin-top: var(--space-5);
}
.involved-card {
  padding: var(--space-5); border-radius: var(--radius-lg);
  background: var(--brand-white); border: 1px solid var(--border-light);
  display: flex; flex-direction: column; gap: var(--space-3);
  transition: transform var(--duration-base) var(--ease-out), box-shadow var(--duration-base);
}
.involved-card:hover {
  transform: translateY(-4px); box-shadow: var(--shadow-md);
}
.involved-card-icon {
  width: 52px; height: 52px; border-radius: var(--radius-md);
  background: var(--brand-red-light); display: flex; align-items: center;
  justify-content: center; font-size: 1.6rem; flex-shrink: 0;
}
.involved-card h3 { font-size: 1.15rem; font-weight: 700; color: var(--brand-navy); }
.involved-card p { font-size: 0.95rem; color: var(--text-secondary); line-height: 1.55; flex: 1; }
.involved-card .btn { align-self: flex-start; margin-top: auto; }

/* ── News Carousel ── */
.news-wrapper { position: relative; margin-top: var(--space-5); }

.news-carousel {
  display: flex; gap: var(--space-4); overflow: hidden;
  scroll-behavior: smooth;
}
.news-card {
  min-width: calc(50% - var(--space-2)); flex-shrink: 0;
  background: var(--brand-white); border: 1px solid var(--border-light);
  border-radius: var(--radius-lg); padding: var(--space-5); overflow: hidden;
  transition: box-shadow var(--duration-base);
}
.news-card:hover { box-shadow: var(--shadow-md); }

.news-card-tag {
  display: inline-block; padding: 4px 12px; font-size: 0.78rem; font-weight: 700;
  letter-spacing: 0.04em; text-transform: uppercase; border-radius: 100px;
  background: var(--brand-red-light); color: var(--brand-red); margin-bottom: var(--space-3);
}
.news-card h3 { font-size: 1.1rem; font-weight: 700; color: var(--text-primary); margin-bottom: var(--space-2); line-height: 1.35; }
.news-card p { font-size: 0.925rem; color: var(--text-secondary); line-height: 1.55; }

.news-controls {
  display: flex; align-items: center; gap: var(--space-3); margin-top: var(--space-4);
  justify-content: center;
}
.news-btn {
  width: 48px; height: 48px; border-radius: 50%; border: 1px solid var(--border-medium);
  background: var(--brand-white); cursor: pointer; display: flex; align-items: center;
  justify-content: center; font-size: 1.1rem; color: var(--text-primary);
  transition: all var(--duration-fast);
}
.news-btn:hover { background: var(--brand-navy); color: var(--brand-white); border-color: var(--brand-navy); }
.news-dots { display: flex; gap: var(--space-2); }
.news-dot {
  width: 10px; height: 10px; border-radius: 50%; border: none; cursor: pointer;
  background: var(--border-medium); transition: all var(--duration-fast);
}
.news-dot.active { background: var(--brand-red); width: 28px; border-radius: 10px; }

/* ── Donate CTA Section ── */
.donate-cta-content {
  display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-8); align-items: start;
}

.impact-table {
  width: 100%; border-collapse: collapse; margin-top: var(--space-4);
}
.impact-table th {
  text-align: left; padding: 10px var(--space-3); font-size: 0.8rem; font-weight: 700;
  letter-spacing: 0.06em; text-transform: uppercase; color: var(--text-muted);
  border-bottom: 2px solid var(--border-light);
}
.impact-table td {
  padding: 12px var(--space-3); font-size: 0.95rem; border-bottom: 1px solid var(--border-light);
}
.impact-table tr:last-child td { border-bottom: none; }
.impact-table .amount {
  font-weight: 700; color: var(--brand-navy); white-space: nowrap;
}
.impact-table .custom-amount { color: var(--brand-red); }

.donate-visual {
  background: linear-gradient(160deg, var(--brand-navy), var(--brand-navy-dark));
  border-radius: var(--radius-lg); padding: var(--space-6); color: var(--brand-white);
}
.donate-visual h3 { font-size: 1.5rem; margin-bottom: var(--space-3); }
.donate-visual p { opacity: 0.85; line-height: 1.65; margin-bottom: var(--space-4); }
.donate-visual .highlight-stat {
  font-size: 1.1rem; font-weight: 600; padding: var(--space-3);
  background: oklch(100% 0 0 / 0.08); border-radius: var(--radius-sm);
  margin-bottom: var(--space-4);
}
.donate-visual .highlight-stat strong { color: oklch(80% 0.18 30); }

/* ── Donation Modal ── */
.modal-overlay {
  position: fixed; inset: 0; z-index: 200;
  background: oklch(0% 0 0 / 0.6); display: flex; align-items: center;
  justify-content: center; padding: var(--space-4);
  opacity: 0; pointer-events: none;
  transition: opacity var(--duration-base) var(--ease-out);
}
.modal-overlay.open { opacity: 1; pointer-events: auto; }

.modal {
  background: var(--brand-white); border-radius: var(--radius-lg);
  max-width: 520px; width: 100%; max-height: 90vh; overflow-y: auto;
  box-shadow: var(--shadow-xl); transform: translateY(20px) scale(0.97);
  transition: transform var(--duration-slow) var(--ease-out);
}
.modal-overlay.open .modal { transform: translateY(0) scale(1); }

.modal-header {
  display: flex; align-items: center; justify-content: space-between;
  padding: var(--space-4) var(--space-5); border-bottom: 1px solid var(--border-light);
}
.modal-header h2 { font-size: 1.3rem; font-weight: 700; color: var(--brand-navy); }
.modal-close {
  width: 40px; height: 40px; border-radius: 50%; border: none; background: var(--bg-warm);
  cursor: pointer; font-size: 1.2rem; display: flex; align-items: center; justify-content: center;
  color: var(--text-muted); transition: all var(--duration-fast);
}
.modal-close:hover { background: var(--border-light); color: var(--text-primary); }

.modal-body { padding: var(--space-5); }

.amount-grid {
  display: grid; grid-template-columns: repeat(2, 1fr); gap: var(--space-3);
  margin-bottom: var(--space-4);
}
.amount-option {
  position: relative;
}
.amount-option input { position: absolute; opacity: 0; pointer-events: none; }
.amount-option label {
  display: flex; flex-direction: column; align-items: center; gap: var(--space-1);
  padding: var(--space-4); border: 2px solid var(--border-light);
  border-radius: var(--radius-md); cursor: pointer;
  transition: all var(--duration-fast); text-align: center;
}
.amount-option label:hover { border-color: var(--brand-red); background: var(--brand-red-light); }
.amount-option input:checked + label {
  border-color: var(--brand-red); background: var(--brand-red-light);
  box-shadow: 0 0 0 2px oklch(52% 0.20 25 / 0.2);
}
.amount-option .amt { font-size: 1.4rem; font-weight: 800; color: var(--brand-navy); }
.amount-option .amt-impact { font-size: 0.82rem; color: var(--text-secondary); line-height: 1.35; }

.custom-amount-row {
  display: flex; gap: var(--space-2); margin-bottom: var(--space-4);
}
.custom-amount-row input {
  flex: 1; padding: 14px var(--space-3); border: 2px solid var(--border-light);
  border-radius: var(--radius-sm); font-size: 1rem; font-family: var(--font-body);
  transition: border-color var(--duration-fast);
}
.custom-amount-row input:focus { border-color: var(--brand-navy); outline: none; }

.modal-footer { padding: 0 var(--space-5) var(--space-5); }
.modal-footer .btn { width: 100%; }

.modal-body .secure-note {
  text-align: center; font-size: 0.85rem; color: var(--text-muted); margin-top: var(--space-3);
}

/* ── Footer ── */
.site-footer {
  background: oklch(15% 0.02 260); color: oklch(100% 0 0 / 0.75);
  padding: var(--space-8) var(--space-4) var(--space-5);
}

.footer-grid {
  display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--space-6);
  max-width: var(--max-width); margin: 0 auto var(--space-7);
}
.footer-col h4 {
