<!-- ── JavaScript ── -->
<script>
/* ── Mobile Menu ── */
const hamburgerBtn = document.getElementById('hamburgerBtn');
const mobileNav = document.getElementById('mobileNav');
const mobileNavOverlay = document.getElementById('mobileNavOverlay');
let menuOpen = false;

function openMobileMenu() {
  menuOpen = true;
  hamburgerBtn.classList.add('active');
  hamburgerBtn.setAttribute('aria-expanded', 'true');
  mobileNav.classList.add('open');
  mobileNavOverlay.classList.add('active');
  mobileNavOverlay.setAttribute('aria-hidden', 'false');
  document.body.style.overflow = 'hidden';
}

function closeMobileMenu() {
  menuOpen = false;
  hamburgerBtn.classList.remove('active');
  hamburgerBtn.setAttribute('aria-expanded', 'false');
  mobileNav.classList.remove('open');
  mobileNavOverlay.classList.remove('active');
  mobileNavOverlay.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
}

hamburgerBtn.addEventListener('click', () => {
  menuOpen ? closeMobileMenu() : openMobileMenu();
});

mobileNavOverlay.addEventListener('click', closeMobileMenu);

// Close mobile menu when a nav link is clicked
mobileNav.querySelectorAll('a').forEach(link => {
  link.addEventListener('click', closeMobileMenu);
});

// Close on Escape
document.addEventListener('keydown', (e) => {
  if (e.key === 'Escape') {
    if (donateModalOpen) closeDonateModal();
    if (menuOpen) closeMobileMenu();
  }
});

/* ── Sticky Header Shadow ── */
const siteHeader = document.getElementById('siteHeader');
let scrollTicking = false;
window.addEventListener('scroll', () => {
  if (!scrollTicking) {
    requestAnimationFrame(() => {
      siteHeader.classList.toggle('scrolled', window.scrollY > 10);
      scrollTicking = false;
    });
    scrollTicking = true;
  }
});

/* ── Donation Modal ── */
const donateModalOverlay = document.getElementById('donateModalOverlay');
const donateFeedback = document.getElementById('donateFeedback');
let donateModalOpen = false;

function openDonateModal() {
  donateModalOpen = true;
  donateModalOverlay.classList.add('open');
  donateModalOverlay.setAttribute('aria-hidden', 'false');
  donateFeedback.textContent = '';
  document.body.style.overflow = 'hidden';
}

function closeDonateModal() {
  donateModalOpen = false;
  donateModalOverlay.classList.remove('open');
  donateModalOverlay.setAttribute('aria-hidden', 'true');
  document.body.style.overflow = '';
}

donateModalOverlay.addEventListener('click', (e) => {
  if (e.target === donateModalOverlay) closeDonateModal();
});

function handleDonate() {
  const checked = document.querySelector('input[name="donationAmount"]:checked');
  const customInput = document.getElementById('customAmount');
  let amount;

  if (customInput.value && parseInt(customInput.value) > 0) {
    amount = '$' + parseInt(customInput.value).toLocaleString();
  } else if (checked) {
    amount = '$' + checked.value;
  } else {
    amount = '$50';
  }

  donateFeedback.textContent = 'Thank you! Your ' + amount + ' donation will help communities in crisis. (Demo — no payment processed)';
  donateFeedback.style.color = 'var(--brand-navy)';

  setTimeout(() => {
    if (donateModalOpen) closeDonateModal();
  }, 2000);
}

// Sync custom amount to deselect radio buttons
document.getElementById('customAmount').addEventListener('input', function() {
  if (this.value) {
    document.querySelectorAll('input[name="donationAmount"]').forEach(r => r.checked = false);
  }
});

document.querySelectorAll('input[name="donationAmount"]').forEach(radio => {
  radio.addEventListener('change', () => {
    document.getElementById('customAmount').value = '';
  });
});

/* ── Animated Counters ── */
function animateCounter(el) {
  const target = parseInt(el.dataset.counter);
  const suffix = el.dataset.suffix || '';
  const prefix = el.dataset.prefix || '';
  const duration = 2000; // ms
  const startTime = performance.now();

  function update(now) {
    const elapsed = now - startTime;
    const progress = Math.min(elapsed / duration, 1);
    // Ease-out quad
    const eased = 1 - (1 - progress) * (1 - progress);
    const current = Math.floor(eased * target);

    if (target >= 1000) {
      el.textContent = prefix + current.toLocaleString() + suffix;
    } else {
      el.textContent = prefix + current + suffix;
    }

    if (progress < 1) {
      requestAnimationFrame(update);
    } else {
      // Final value
      if (target >= 1000) {
        el.textContent = prefix + target.toLocaleString() + suffix;
      } else {
        el.textContent = prefix + target + suffix;
      }
    }
  }

  requestAnimationFrame(update);
}

// Intersection Observer for counters
const counterElements = document.querySelectorAll('[data-counter]');
const counterObserver = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      animateCounter(entry.target);
      counterObserver.unobserve(entry.target);
    }
  });
}, { threshold: 0.5 });

counterElements.forEach(el => counterObserver.observe(el));

/* ── Program Accordion ── */
const accordionTriggers = document.querySelectorAll('.accordion-trigger');

accordionTriggers.forEach(trigger => {
  trigger.addEventListener('click', () => {
    const item = trigger.parentElement;
    const panel = item.querySelector('.accordion-panel');
    const isActive = item.classList.contains('active');

    // Close all
    document.querySelectorAll('.accordion-item.active').forEach(activeItem => {
      if (activeItem !== item) {
        activeItem.classList.remove('active');
        activeItem.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
        activeItem.querySelector('.accordion-panel').style.maxHeight = '0';
      }
    });

    // Toggle current
    if (isActive) {
      item.classList.remove('active');
      trigger.setAttribute('aria-expanded', 'false');
      panel.style.maxHeight = '0';
    } else {
      item.classList.add('active');
      trigger.setAttribute('aria-expanded', 'true');
      panel.style.maxHeight = panel.scrollHeight + 'px';
    }
  });
});

/* ── News Carousel ── */
const carousel = document.getElementById('newsCarousel');
const prevBtn = document.getElementById('newsPrev');
const nextBtn = document.getElementById('newsNext');
const dots = document.querySelectorAll('.news-dot');
const newsCards = carousel.querySelectorAll('.news-card');
let currentSlide = 0;
const totalSlides = newsCards.length;

function updateCarousel() {
  const cardWidth = newsCards[0].offsetWidth + 16; // card width + gap
  carousel.scrollTo({ left: currentSlide * cardWidth, behavior: 'smooth' });

  dots.forEach((dot, i) => {
    dot.classList.toggle('active', i === currentSlide);
  });
}

prevBtn.addEventListener('click', () => {
  currentSlide = currentSlide > 0 ? currentSlide - 1 : totalSlides - 1;
  updateCarousel();
});

nextBtn.addEventListener('click', () => {
  currentSlide = currentSlide < totalSlides - 1 ? currentSlide + 1 : 0;
  updateCarousel();
});

dots.forEach(dot => {
  dot.addEventListener('click', () => {
    currentSlide = parseInt(dot.getAttribute('aria-label').match(/\d+/)[0]) - 1;
    updateCarousel();
  });
});

// Handle window resize to recalculate scroll positions
let resizeTimeout;
window.addEventListener('resize', () => {
  clearTimeout(resizeTimeout);
  resizeTimeout = setTimeout(() => {
    const cardWidth = newsCards[0].offsetWidth + 16;
    carousel.scrollTo({ left: currentSlide * cardWidth, behavior: 'instant' });
  }, 150);
});

// Keyboard navigation for carousel
carousel.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft') { prevBtn.click(); e.preventDefault(); }
  if (e.key === 'ArrowRight') { nextBtn.click(); e.preventDefault(); }
});

// Initialize carousel
updateCarousel();
</script>

</body>
</html>
